:#1e2a23;--text:#edf6f0;--muted:#adbbb1;--border:#304038;--shadow:0 16px 45px #0006}.dark .nav{background:#101612f5}.dark .badge{background:#17211b;color:#79dca5}@media(max-width:850px){.links{display:none}.tripGrid,.steps{grid-template-columns:1fr}.attrGrid{grid-template-columns:1fr}.hero{min-height:560px}.head{display:block}.head p{margin-top:8px}.form{grid-template-columns:1fr}.field.full{grid-column:auto}}@media(max-width:520px){.actions .outline{display:none}.section{padding:55px 0}.hero .wrap{padding:55px 0}.hero h1{letter-spacing:-1px}.smallGrid{grid-template-columns:1fr}.feature{min-height:360px}.footerIn{display:block}}
