<script>
const seed=<?=json_encode($seed,JSON_UNESCAPED_SLASHES)?>;let trips=[];let attrIndex=0;
const attractions=[
 ['Ngorongoro Crater','Wildlife and breathtaking crater views.','https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=1200&q=85'],
 ['Serengeti National Park','Iconic savannahs and unforgettable wildlife.','https://images.unsplash.com/photo-1519659528534-7fd733a832a0?auto=format&fit=crop&w=1200&q=85'],
 ['Mount Kilimanjaro','Africa’s highest mountain and a legendary adventure.','https://images.unsplash.com/photo-1609198092458-38a293c7ac4b?auto=format&fit=crop&w=1200&q=85'],
 ['Zanzibar','Indian Ocean beaches, culture and Stone Town.','https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?auto=format&fit=crop&w=1200&q=85'],
 ['Tarangire National Park','Baobabs, elephants and open wilderness.','https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=1200&q=85'],
 ['Lake Manyara','Scenic landscapes and rich birdlife.','https://images.unsplash.com/photo-1547970810-dc1cae47a31c?auto=format&fit=crop&w=1200&q=85']
];
function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[m]))}
function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}
function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),3500)}
function remaining(date){let d=Math.max(0,new Date(date.replace(' ','T')).getTime()-Date.now());let sec=Math.floor(d/1000);let days=Math.floor(sec/86400);sec%=86400;let h=Math.floor(sec/3600);sec%=3600;let m=Math.floor(sec/60);let s=sec%60;return [days,h,m,s]}
function render(){const g=document.getElementById('tripGrid');if(!trips.length){g.innerHTML='<div class="empty">No upcoming trips are published yet. Be the first to organize one.</div>';return}g.innerHTML=trips.map(t=>{let joined=Number(t.joined||0),cap=Number(t.capacity||0),[d,h,m,s]=remaining(t.departure_at||t.date);return `<article class="card"><div class="tripImg" style="background-image:url('${esc(t.image_url||t.image)}')"><span class="badge">Upcoming</span><span class="joined">${joined}/${cap} joined</span></div><div class="body"><h3>${esc(t.title)}</h3><div class="meta"><span>📍 ${esc(t.destination)}</span><span>🗓 ${new Date((t.departure_at||t.date).replace(' ','T')).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}</span></div><p class="desc">${esc(t.description)}</p><div class="count"><div class="unit"><b>${String(d).padStart(2,'0')}</b><small>DAYS</small></div><div class="unit"><b>${String(h).padStart(2,'0')}</b><small>HOURS</small></div><div class="unit"><b>${String(m).padStart(2,'0')}</b><small>MIN</small></div><div class="unit"><b>${String(s).padStart(2,'0')}</b><small>SEC</small></div></div><button class="btn" onclick="joinTrip(${Number(t.id||0)},'${esc(t.title)}')">Join this trip</button></div></article>`}).join('')}
async function loadTrips(){try{const r=await fetch('api.php?action=list',{cache:'no-store'});const j=await r.json();if(j.ok&&Array.isArray(j.trips)&&j.trips.length){trips=j.trips}else{trips=seed.map((x,i)=>({...x,id:0,joined:0,departure_at:x.date}))}render()}catch(e){trips=seed.map(x=>({...x,id:0,joined:0,departure_at:x.date}));render()}}
function joinTrip(id,title){if(!id){toast('Database setup is still required before registrations can be saved.');return}document.getElementById('joinId').value=id;document.getElementById('joinTitle').textContent='Join: '+title;openModal('join')}
document.getElementById('joinForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData();fd.append('trip_id',document.getElementById('joinId').value);fd.append('name',document.getElementById('name').value);fd.append('phone',document.getElementById('phone').value);fd.append('email',document.getElementById('email').value);fd.append('people',document.getElementById('people').value);fd.append('message',document.getElementById('message').value);const r=await fetch('api.php?action=join',{method:'POST',body:fd});const j=await r.json();if(j.ok){closeModal('join');e.target.reset();toast('Registration confirmed — you joined the trip.');loadTrips()}else toast(j.error||'Could not register.')});
document.getElementById('createForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData();fd.append('title',ctitle.value);fd.append('destination',cdestination.value);fd.append('departure',cdate.value);fd.append('capacity',ccapacity.value);fd.append('description',cdescription.value);fd.append('organizer',corganizer.value);fd.append('phone',cphone.value);const r=await fetch('api.php?action=create',{method:'POST',body:fd});const j=await r.json();if(j.ok){closeModal('organize');e.target.reset();toast('Your trip is now published.');loadTrips();document.getElementById('trips').scrollIntoView({behavior:'smooth'})}else toast(j.error||'Could not publish trip.')});
function renderAttractions(){const a=attractions[attrIndex%attractions.length];document.getElementById('feature').style.backgroundImage=`url('${a[2]}')`;document.getElementById('ftitle').textContent=a[0];document.getElementById('fdesc').textContent=a[1];const rest=[1,2,3,4].map((_,i)=>attractions[(attrIndex+i+1)%attractions.length]);document.getElementById('smallGrid').innerHTML=rest.map(a=>`<div class="small" style="background-image:url('${a[2]}')"><div class="smallText"><h4>${a[0]}</h4><p>${a[1]}</p></div></div>`).join('')}
renderAttractions();setInterval(()=>{attrIndex++;renderAttractions()},6000);loadTrips();setInterval(render,1000);setInterval(loadTrips,30000);
document.getElementById('theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('ttheme',document.body.classList.contains('dark')?'dark':'light');document.getElementById('theme').textContent=document.body.classList.contains('dark')?'☀':'☾'};if(localStorage.getItem('ttheme')==='dark'){document.body.classList.add('dark');document.getElementById('theme').textContent='☀'}
</script></body></html>